package com.aoo.bcg.telemetry;
import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.Clock;import java.util.HexFormat;
/** Validates short-lived player assertions; request bodies never establish identity. */
public final class TelemetryAuthenticator {private final byte[] secret;private final Clock clock;public TelemetryAuthenticator(String secret,Clock clock){if(secret==null||secret.length()<32)throw new IllegalArgumentException("telemetry auth secret must contain at least 32 characters");this.secret=secret.getBytes(StandardCharsets.UTF_8);this.clock=clock;}public long authenticate(String h){try{if(h==null||!h.startsWith("Bearer "))throw new SecurityException("valid player bearer required");String[]p=h.substring(7).split("\\.",-1);long now=clock.instant().getEpochSecond(),id=Long.parseLong(p[0]),exp=Long.parseLong(p[1]);if(p.length!=3||id<=0||exp<now||exp>now+300)throw new SecurityException("valid player bearer required");Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret,"HmacSHA256"));if(!MessageDigest.isEqual(m.doFinal((p[0]+"."+p[1]).getBytes(StandardCharsets.UTF_8)),HexFormat.of().parseHex(p[2])))throw new SecurityException("valid player bearer required");return id;}catch(SecurityException x){throw x;}catch(Exception x){throw new SecurityException("valid player bearer required");}}}
